<body>
  <div class="toolbar">
    <div><b>📄 BelaFarma • Relatório de Compras (${U.length} produtos)</b></div>
    <div>
      <button class="btn btn-primary" onclick="window.print()">🖨️ Imprimir / Salvar PDF</button>
      <button class="btn" style="background: #334155; color: white; margin-left: 6px;" onclick="window.close()">✕ Fechar</button>
    </div>
  </div>
  <div class="sheet">
    <div style="display: flex; justify-content: space-between; border-bottom: 2px solid #0f172a; padding-bottom: 8px;">
      <div>
        <h1>BelaFarma • Relatório de Compras</h1>
        <p style="margin: 2px 0 0; color: #64748b; font-size: 10px;">Produtos selecionados e cotados nos portais</p>
      </div>
      <div style="text-align: right; font-size: 9.5px; color: #475569;">
        <div><b>Emissão:</b> ${Be} às ${Me}</div>
        <div><b>Itens:</b> ${U.length} produtos (${K} un)</div>
        <div><b>Total:</b> R$ ${M.toFixed(2)}</div>
      </div>
    </div>
    <table>
      <thead>
        <tr>
          <th style="width: 25px;" class="text-center">#</th>
          <th>Produto / Descrição</th>
          <th style="width: 85px;" class="text-center">EAN</th>
          <th style="width: 30px;" class="text-center">Curva</th>
          <th style="width: 35px;" class="text-right">Saldo</th>
          <th style="width: 35px;" class="text-center">Qtd</th>
          <th style="width: 120px;">1º Fornecedor</th>
          <th style="width: 60px;" class="text-right">Preço Cot.</th>
          <th style="width: 60px;" class="text-right">Últ. Compra</th>
          <th style="width: 65px;" class="text-right">Subtotal</th>
        </tr>
      </thead>
      <tbody>
        ${U.map((me,Se)=>`
          <tr>
            <td class="text-center">${Se+1}</td>
            <td><b>${String(me.descricao||"").replace(/</g,"&lt;")}</b></td>
            <td class="text-center font-mono">${me.ean||"—"}</td>
            <td class="text-center font-bold">${me.curva_abc||"—"}</td>
            <td class="text-right">${me.saldo}</td>
            <td class="text-center font-bold" style="color: #0284c7;">${me.qtd_sugerida_7d||1}</td>
            <td><b>${me.fornecedor_1||"—"}</b></td>
            <td class="text-right font-mono">R$ ${(Number(me.preco_1)||0).toFixed(2)}</td>
            <td class="text-right font-mono" style="color: #64748b;">${Number(me.preco_ult_compra||me.custo_unitario)?`R$ ${Number(me.preco_ult_compra||me.custo_unitario).toFixed(2)}`:"—"}</td>
            <td class="text-right font-mono font-bold">R$ ${(Number(me.subtotal_7d)||0).toFixed(2)}</td>
          </tr>
        `).join("")}
      </tbody>
      <tfoot>
        <tr style="background: #f1f5f9; font-weight: bold;">
          <td colspan="5" class="text-right">Totais:</td>
          <td class="text-center" style="color: #0284c7;">${K} un</td>
          <td colspan="3" class="text-right">Valor Total Estimado:</td>
          <td class="text-right font-mono" style="font-size: 11px;">R$ ${M.toFixed(2)}</td>
        </tr>
      </tfoot>
    </table>
  </div>
</body>
